import { describe, expect, it } from "vitest";
import type { RecipeDraft, RecipeIdea, RecipeIdeaId, Result } from "@weekly-planner/domain";
import type { RecipeIdeaRepository } from "../src/ports/recipe-ideas.js";
import { NoteIdea, UseOwnRecipe } from "../src/use-cases/recipe-ideas.js";
import type { DraftRecipeImport } from "../src/use-cases/recipe-import.js";
import { AC, FakeClock, ME, SequenceIds } from "./support/in-memory.js";

const HOUR = 3_600_000;

class InMemoryIdeas implements RecipeIdeaRepository {
  readonly byId = new Map<RecipeIdeaId, RecipeIdea>();
  saves = 0;
  async get(id: RecipeIdeaId) {
    return this.byId.get(id) ?? null;
  }
  async save(idea: RecipeIdea) {
    this.saves++;
    this.byId.set(idea.id, idea);
  }
  async remove(id: RecipeIdeaId) {
    this.byId.delete(id);
  }
  async listAll() {
    return [...this.byId.values()];
  }
}

/** The import's ReadRecipe: records the sources it was handed. */
class FakeDraftImport implements Pick<DraftRecipeImport, "execute"> {
  readonly read: { member: string; address?: string; text?: string }[] = [];
  result: Result<RecipeDraft> = { ok: true, value: { name: "Kürbisgnocchi" } as RecipeDraft };
  async execute(cmd: { member: RecipeIdea["addedBy"]; address?: string; text?: string }) {
    this.read.push(cmd);
    return this.result;
  }
}

/** Moves the fake clock forward by whole hours (it counts in hours of a day). */
const advance = (clock: FakeClock, ms: number) => {
  const target = clock.now() + ms;
  const d = new Date(target);
  clock.date = d.toISOString().slice(0, 10) as FakeClock["date"];
  clock.hour = d.getUTCHours();
  expect(clock.now()).toBe(target);
};

async function anIdea() {
  const repo = new InMemoryIdeas();
  const draft = new FakeDraftImport();
  const clock = new FakeClock();
  const noted = await new NoteIdea({ ideas: repo, clock, ids: new SequenceIds() }).execute({
    member: ME,
    title: "Kürbis",
  });
  if (!noted.ok) throw new Error(noted.reason);
  advance(clock, 2 * HOUR);
  return { repo, draft, clock, idea: noted.value, own: new UseOwnRecipe({ ideas: repo, clock, draft }) };
}

describe("UseOwnRecipe: exactly one of link or text", () => {
  const refused: [string, { address?: string; text?: string }][] = [
    ["neither", {}],
    ["neither, both empty", { address: "", text: "" }],
    ["neither, both only whitespace", { address: "  ", text: "\n\t " }],
    ["both", { address: "https://example.org/mine", text: "Kürbis schälen ..." }],
  ];

  for (const [name, source] of refused) {
    it(`tells the member to give one source and changes nothing (${name})`, async () => {
      const h = await anIdea();
      const before = await h.repo.get(h.idea.id);
      const savesBefore = h.repo.saves;
      expect(await h.own.execute({ member: AC, idea: h.idea.id, ...source })).toEqual({
        ok: false,
        reason: "need_one_source",
      });
      expect(await h.repo.get(h.idea.id)).toEqual(before);
      expect((await h.repo.get(h.idea.id))?.lastTouchedAt).toBe(h.idea.lastTouchedAt);
      expect(h.repo.saves).toBe(savesBefore);
      expect(h.draft.read).toEqual([]);
    });
  }

  it("takes a link with only whitespace beside it as the link alone, and moves the idea's clock", async () => {
    const h = await anIdea();
    expect(
      (await h.own.execute({ member: ME, idea: h.idea.id, address: "https://example.org/mine", text: "  " })).ok,
    ).toBe(true);
    expect(h.draft.read).toHaveLength(1);
    expect(h.draft.read[0]?.address).toBe("https://example.org/mine");
    expect(h.draft.read[0]?.text?.trim() ?? "").toBe("");
    expect((await h.repo.get(h.idea.id))?.lastTouchedAt).toBe(h.clock.now());
  });

  it("takes text with only whitespace beside it as the text alone, and moves the idea's clock", async () => {
    const h = await anIdea();
    expect((await h.own.execute({ member: ME, idea: h.idea.id, address: " ", text: "Kürbis schälen ..." })).ok).toBe(
      true,
    );
    expect(h.draft.read).toHaveLength(1);
    expect(h.draft.read[0]?.text).toBe("Kürbis schälen ...");
    expect(h.draft.read[0]?.address?.trim() ?? "").toBe("");
    expect((await h.repo.get(h.idea.id))?.lastTouchedAt).toBe(h.clock.now());
  });
});
